func kindKey(r TxnRow) string {
	k := "tx.kind-" + r.Kind
	if !r.Confirmed {
		k += "-pending"
	}
	return k
}

func kindIcon(kind string) string {
	switch kind {
	case "in":
		return "call_received"
	case "out":
		return "call_made"
	}
	return "swap_horiz"
}

